"""Golden wire contracts captured from the pre-T24 dirty baseline, not regenerated by tests."""
from __future__ import annotations

import json
from copy import deepcopy
from pathlib import Path

import pytest

from pipelines_v2.api import WorkflowSpec
from pipelines_v2.engine.registry import engine_from_dict
from pipelines_v2.operations.interventions.recipes import ActivationPatchSpec, PATCH_LOADERS
from pipelines_v2.operations.registry import BUILTIN_OPERATION_KINDS, operation_spec_from_dict

FIXTURES = json.loads((Path(__file__).parent / 'fixtures/legacy_serialization_v1.json').read_text())


def with_explicit_legacy_coordinates(payload):
    """Keep the old golden bytes; assert the deliberate coordinate migration."""
    expected = deepcopy(payload)
    if expected.get('kind') == 'capture':
        for site in expected['sites']:
            if 'site' in site:
                site['layer_indexing'] = 'vllm_aux'
    for step in expected.get('steps', []):
        step['spec'] = with_explicit_legacy_coordinates(step['spec'])
    return expected


def test_golden_covers_every_builtin_operation_and_patch_family():
    assert {item['kind'] for item in FIXTURES['operations']} == BUILTIN_OPERATION_KINDS
    # New native/scale codecs have their own oracles; preserve pre-T24 goldens.
    assert {item['kind'] for item in FIXTURES['patches']} | {'scale_patch', 'native_coordinate_patch'} == set(PATCH_LOADERS)


@pytest.mark.parametrize('fixture', FIXTURES['operations'], ids=lambda item: item['kind'])
def test_legacy_operation_sparse_defaults_and_canonical_roundtrip(fixture):
    for payload in (fixture['input'], fixture['payload']):
        spec = operation_spec_from_dict(payload)
        expected = with_explicit_legacy_coordinates(fixture['payload'])
        assert spec.to_dict() == expected
        if fixture['kind'] == 'capture':
            assert spec.spec_hash() != fixture['spec_hash']
            assert spec.semantic_hash() != fixture['semantic_hash']
            assert operation_spec_from_dict(spec.to_dict()).to_dict() == expected
        else:
            assert spec.spec_hash() == fixture['spec_hash']
            assert spec.semantic_hash() == fixture['semantic_hash']


@pytest.mark.parametrize('fixture', FIXTURES['patches'], ids=lambda item: item['kind'])
def test_legacy_patch_roundtrip(fixture):
    for payload in (fixture['input'], fixture['payload']):
        patch = ActivationPatchSpec.from_dict(payload)
        assert patch.to_dict() == fixture['payload']
        assert patch.semantic_dict() == fixture['semantic']


@pytest.mark.parametrize('fixture', FIXTURES['engines'])
def test_legacy_engine_identity(fixture):
    engine = engine_from_dict(fixture['payload'])
    assert engine.identity() == fixture['payload']
    assert engine.semantic_identity() == fixture['semantic']


def test_legacy_workflow_snapshot():
    fixture = FIXTURES['workflow']
    workflow = WorkflowSpec.from_dict(fixture['payload'])
    assert workflow.to_dict() == with_explicit_legacy_coordinates(fixture['payload'])
    assert workflow.spec_hash() != fixture['spec_hash']
    assert workflow.semantic_hash() != fixture['semantic_hash']
    assert WorkflowSpec.from_dict(workflow.to_dict()).to_dict() == workflow.to_dict()


def test_residual_and_moe_feature_wire_payloads_match_baseline():
    import numpy as np
    from pipelines_v2.storage.features import encode_feature_payload, decode_feature_payload, feature_storage_format
    fixtures = json.loads((Path(__file__).parent / 'fixtures/legacy_features_v1.json').read_text())
    def restore(value):
        if isinstance(value, dict):
            if set(value) == {'array','dtype'}:
                return np.asarray(value['array'], dtype=value['dtype'])
            return {key:restore(item) for key,item in value.items()}
        if isinstance(value, list):
            return [restore(item) for item in value]
        return value
    for fixture in fixtures:
        payload = restore(fixture['payload'])
        metadata, tensors = encode_feature_payload(payload, tensor_key_prefix='fixture_')
        assert feature_storage_format(payload) == fixture['format']
        assert metadata == fixture['metadata']
        expected = restore(fixture['tensors'])
        assert tensors.keys() == expected.keys()
        for key in tensors:
            assert tensors[key].dtype == expected[key].dtype
            np.testing.assert_array_equal(tensors[key], expected[key])
        # Decoding still restores the actual captured arrays, not encoded refs.
        decoded = decode_feature_payload(metadata, tensors)
        if payload['kind'] == 'residual':
            np.testing.assert_array_equal(decoded['layers']['0']['a']['values'], [[1,2],[3,4]])
        else:
            np.testing.assert_array_equal(decoded['layers']['0']['a']['routing'], [[0,1]])
